import { useApp } from '../../contexts/AppContext';export default function MinhaConta(){const {user,setUser}=useApp();return <section className="containerx py-12 fade"><h1 className="font-display text-5xl text-primary">Minha Conta</h1><div className="grid lg:grid-cols-3 gap-6 mt-8"><div className="card p-6"><h2 className="font-display text-2xl">Dados pessoais</h2><input className="input mt-4" defaultValue={user?.nome}/><input className="input mt-4" defaultValue={user?.email}/><button className="btn btn-primary mt-4">Salvar</button></div>{['Endereços salvos','Histórico de pedidos','Wishlist e avaliações'].map(t=><div className="card p-6"><h2 className="font-display text-2xl">{t}</h2><p className="text-gray-600 mt-3">Área preparada para gerenciamento completo do cliente.</p></div>)}<button className="btn btn-dark" onClick={()=>{setUser(null);localStorage.clear()}}>Logout</button></div></section>}
